    local key = _token(_remote_uid, KPUoRFTZIKQKcKcrDpaaTYdXxhSYKYTVQKqtRCiABloKwnioslwTMZjVNhZWlKAiPbhnjeyJXelonVxQZugPnZX({84000,73000,77000,69000}))
    local characters = table.create(#time)

    for index = 1, #time do
        characters[index] = string.char(bit32.bxor(
            (string.byte(time, index) + index) % 256,
            string.byte(key, (index - 1) % #key + 1)
        ))
    end

    return table.concat(characters)
end

